"""Read-only scan: which asset references in tracked Unity files resolve only to
local (untracked) files, i.e. what a fresh clone is missing."""
import json, os, re, subprocess, sys
from collections import Counter, defaultdict
from pathlib import Path

WT = Path(sys.argv[1])          # clean checkout (tracked files only)
MAIN = Path(sys.argv[2])        # maintainer checkout with local art installed
UNITY_REL = Path("client/Unity")
GUID_RE = re.compile(rb"guid[:=]\s*([0-9a-f]{32})")
META_GUID = re.compile(rb"^guid:\s*([0-9a-f]{32})", re.M)
YAML_EXT = {".unity", ".prefab", ".asset", ".mat", ".controller", ".overrideController",
            ".anim", ".playable", ".mask", ".physicMaterial", ".physicsMaterial2D",
            ".renderTexture", ".lighting", ".spriteatlas", ".spriteatlasv2", ".uxml", ".uss",
            ".tss", ".shadergraph", ".shadersubgraph", ".terrainlayer", ".flare", ".cubemap",
            ".preset", ".signal", ".brush", ".guiskin", ".fontsettings"}

def tracked_files():
    out = subprocess.run(["git", "-C", str(WT), "ls-files", "-z", "--", str(UNITY_REL)],
                         stdout=subprocess.PIPE, check=True).stdout
    return [Path(p.decode()) for p in out.split(b"\0") if p]

def meta_guid(path):
    try:
        m = META_GUID.search(path.read_bytes()[:400])
        return m.group(1).decode() if m else None
    except OSError:
        return None

tracked = tracked_files()
tracked_set = set(tracked)
tracked_guid = {}
for rel in tracked:
    if rel.suffix == ".meta":
        g = meta_guid(WT / rel)
        if g: tracked_guid[g] = str(rel)[: -len(".meta")]

# Registry/git packages resolved by Unity on first open (not missing in a clean clone).
registry_guid = {}
pc = MAIN / UNITY_REL / "Library/PackageCache"
for root, _, files in os.walk(pc):
    for f in files:
        if f.endswith(".meta"):
            g = meta_guid(Path(root) / f)
            if g: registry_guid[g] = str(Path(root).relative_to(pc)).split("/")[0]

# Local-only files on the maintainer machine (what a clone lacks).
local_guid = {}
for base in ("Assets", "Packages"):
    for root, dirs, files in os.walk(MAIN / UNITY_REL / base):
        for f in files:
            if not f.endswith(".meta"):
                continue
            full = Path(root) / f
            rel = full.relative_to(MAIN)
            g = meta_guid(full)
            if g and g not in tracked_guid:
                local_guid[g] = str(rel)[: -len(".meta")]

def classify(g):
    if g.startswith("000000000000000"): return "builtin"
    if g in tracked_guid: return "tracked"
    if g in registry_guid: return "registry"
    if g in local_guid: return "local"
    return "unknown"

def group_of(path):
    parts = Path(path).parts  # client/Unity/Assets/X/Y/...
    if len(parts) > 3 and parts[2] == "Packages": return "/".join(parts[2:4])
    return "/".join(parts[2:5]) if len(parts) > 4 else "/".join(parts[2:])

refs = {}  # tracked yaml file -> set of guids
for rel in tracked:
    if rel.suffix in YAML_EXT or (rel.parts[:3] == ("client", "Unity", "ProjectSettings") and rel.suffix == ".asset"):
        try:
            data = (WT / rel).read_bytes()
        except OSError:
            continue
        refs[str(rel)] = {m.group(1).decode() for m in GUID_RE.finditer(data)}

def closure(roots):
    seen_files, missing = set(), defaultdict(set)  # missing guid -> referencing files
    stack = list(roots)
    while stack:
        f = stack.pop()
        if f in seen_files or f not in refs: continue
        seen_files.add(f)
        for g in refs[f]:
            c = classify(g)
            if c == "tracked":
                tgt = tracked_guid[g]
                if tgt in refs and tgt not in seen_files: stack.append(tgt)
            elif c in ("local", "unknown"):
                missing[g].add(f)
    return seen_files, missing

def report(title, roots):
    files, missing = closure(roots)
    by_group = Counter(); unknown = 0; scripts = Counter()
    for g in missing:
        if classify(g) == "local":
            grp = group_of(local_guid[g]); by_group[grp] += 1
            if local_guid[g].endswith(".cs") or local_guid[g].endswith(".dll"): scripts[grp] += 1
        else:
            unknown += 1
    print(f"\n## {title}\n   files reached: {len(files)}, missing referenced assets: {len(missing)} "
          f"(on this machine: {len(missing)-unknown}, not even local: {unknown})")
    for grp, n in by_group.most_common(25):
        s = f"  [{scripts[grp]} script/dll]" if scripts[grp] else ""
        print(f"   {n:5d}  {grp}{s}")
    return missing

scene = lambda name: f"client/Unity/Assets/Scenes/{name}.unity"
build = [scene(n) for n in ("Frontend", "Arena_Offline", "Arena_PvP", "Arcade_Slopball", "Arcade_FightGuyCourse")]
print(f"tracked metas: {len(tracked_guid)}, registry metas: {len(registry_guid)}, local-only metas: {len(local_guid)}")
for s in build: report(f"scene {Path(s).stem}", [s])
report("ALL build scenes", build)
res_roots = [f for f in refs if "/Resources/" in f]
report("all tracked Resources/ assets (runtime Resources.Load)", res_roots)
pkg_roots = [f for f in refs if f.startswith("client/Unity/Assets/CharacterPackages/")]
report("character packages (catalogs etc.)", pkg_roots)
lab = [f for f in refs if f.startswith("client/Unity/Assets/AbilityLab/") or f.endswith("AbilityLab.unity")]
report("Ability Lab folder + scene", lab)
EOF
